1	import { Router } from "express";
2	import { z } from "zod";
3	import type { Db } from "@paperclipai/db";
4	import { assertBoard, assertCompanyAccess } from "./authz.js";
5	import { inboxDismissalService, logActivity } from "../services/index.js";
6	import { expressHandler } from "../http/express-adapter.js";
7	import type { Handler } from "../http/types.js";
8	import type { StorageService } from "../storage/types.js";
9	
10	const inboxDismissalSchema = z.object({
11	  itemKey: z.string().trim().min(1).regex(/^(approval|join|run):.+$/, "Unsupported inbox item key"),
12	});
13	
14	function buildHandlers(db: Db) {
15	  const svc = inboxDismissalService(db);
16	
17	  // server/src/routes/inbox-dismissals.ts:16
18	  const getInboxDismissals: Handler = async (ctx) => {
19	    const companyId = ctx.param("companyId") ?? "";
20	    assertCompanyAccess(ctx, companyId);
21	    assertBoard(ctx);
22	    const dismissals = await svc.list(companyId, (ctx.actor as { userId: string }).userId);
23	    return Response.json(dismissals);
24	  };
25	
26	  // server/src/routes/inbox-dismissals.ts:31
27	  const postInboxDismissal: Handler = async (ctx) => {
28	    const companyId = ctx.param("companyId") ?? "";
29	    assertCompanyAccess(ctx, companyId);
30	    assertBoard(ctx);
31	    const boardActor = ctx.actor as { type: "board"; userId: string; runId?: string };
32	
33	    const body = await ctx.json();
34	    const parsed = inboxDismissalSchema.parse(body);
35	
36	    const dismissal = await svc.dismiss(companyId, boardActor.userId, parsed.itemKey, new Date());
37	
38	    await logActivity(db, {
39	      companyId,
40	      actorType: "user",
41	      actorId: boardActor.userId,
42	      agentId: null,
43	      runId: ctx.actor?.runId ?? null,
44	      action: "inbox.dismissed",
45	      entityType: "company",
46	      entityId: companyId,
47	      details: {
48	        userId: boardActor.userId,
49	        itemKey: dismissal.itemKey,
50	        dismissedAt: dismissal.dismissedAt,
51	      },
52	    });
53	
54	    return Response.json(dismissal, { status: 201 });
55	  };
56	
57	  return { getInboxDismissals, postInboxDismissal };
58	}
59	
60	export function inboxDismissalRoutes(db: Db) {
61	  const router = Router();
62	  const { getInboxDismissals, postInboxDismissal } = buildHandlers(db);
63	
64	  const storageSentinel = new Proxy({} as StorageService, {
65	    get(_target, prop) {
66	      throw new Error(`inboxDismissal handler unexpectedly accessed storage.${String(prop)}`);
67	    },
68	  });
69	  const deps = { db, storage: storageSentinel };
70	
71	  router.get("/companies/:companyId/inbox-dismissals", expressHandler(getInboxDismissals, deps));
72	  router.post("/companies/:companyId/inbox-dismissals", expressHandler(postInboxDismissal, deps));
73	
74	  return router;
75	}
